mapper.select:
select d.document_id, d.document_code, d.title, d.summary, d.file_name, d.file_ext, d.file_size,
       d.file_url, d.file_storage, d.cover_url, d.page_count, d.subject_id, s.subject_name,
       d.school_stage, d.version_id, v.version_name, d.textbook_id, tb.textbook_name,
       d.chapter_id, d.chapter_text, d.category_id, c.category_name, d.tag_names, d.visibility, d.allow_download,
       d.download_price, d.download_count, d.view_count, d.favorite_count, d.convert_status, d.preview_type,
       d.preview_url, d.preview_error, d.audit_status, d.audit_by, d.audit_time, d.audit_remark,
       d.recommend_flag, d.recommend_order, d.status, d.del_flag, d.create_by, d.create_time,
       d.update_by, d.update_time, d.remark,
       ,


               case when fav.favorite_id is not null then true else false end as favorited

           false as favorited

from edu_library_document d
left join edu_subject s on s.subject_id = d.subject_id
left join edu_qb_textbook_version v on v.version_id = d.version_id
left join edu_qb_textbook tb on tb.textbook_id = d.textbook_id
left join edu_library_category c on c.category_id = d.category_id

    left join edu_library_favorite fav on fav.document_id = d.document_id and fav.user_name = #{params.currentUser}


    d.del_flag = '0'
    and d.title like ('%' || #{title} || '%')

        and (
            d.title ilike ('%' || #{keyword} || '%')
            or d.summary ilike ('%' || #{keyword} || '%')
            or d.tag_names ilike ('%' || #{keyword} || '%')
            or d.file_name ilike ('%' || #{keyword} || '%')
        )

    and d.subject_id = #{subjectId}
    and d.school_stage = #{schoolStage}
    and d.version_id = #{versionId}
    and d.textbook_id = #{textbookId}
    and d.chapter_id = #{chapterId}
    and d.category_id = #{categoryId}
    and d.file_ext = #{fileExtFilter}
    and d.visibility = #{visibility}
    and d.audit_status = #{auditStatus}
    and d.status = #{status}
    and d.recommend_flag = #{recommendFlag}
    and d.create_by = #{createBy}
    and d.convert_status = #{convertStatus}

        and d.status = '0' and d.audit_status = '1'
        and (
            d.visibility = 'public'

                or d.visibility = 'school'
                or (d.visibility = 'private' and d.create_by = #{params.currentUser})

        )


        and d.create_by = #{params.currentUser}


order by

    d.view_count desc, d.document_id desc
    d.download_count desc, d.view_count desc, d.document_id desc
    d.recommend_order desc, d.create_time desc
    d.create_time desc, d.document_id desc

mapper.update:
update edu_library_document set del_flag = '2', update_time = CURRENT_TIMESTAMP
where document_id in

    #{documentId}

update edu_library_document
set favorite_count = greatest(coalesce(favorite_count, 0) + #{delta}, 0)
where document_id = #{documentId}

mapper.select:

inner join edu_library_favorite fav on fav.document_id = d.document_id and fav.user_name = #{userName}
where d.del_flag = '0' and d.status = '0' and d.audit_status = '1'
order by fav.create_time desc


where d.del_flag = '0'
  and d.document_id != #{documentId}



      and (d.subject_id = #{subjectId} or d.category_id = #{categoryId})


      and d.subject_id = #{subjectId}


      and d.category_id = #{categoryId}


order by d.view_count desc, d.create_time desc
limit #{limit}
